Context:
This file already uses a PostHog mock via vi.hoisted/vi.mock — `mockCapture` captures every trackEvent call. It also uses `importTelemetry()` to get a fresh module instance per test, and `makeTestDir()` to set up isolated config directories. Reuse these helpers.

The existing test file structure (top of file) provides:
```ts
const { mockCapture, mockIdentify, mockShutdown, mockConstructorOptions } = vi.hoisted(() => ({...}));
vi.mock('posthog-node', () => ({ PostHog: class MockPostHog {...} }));

const importTelemetry = async () => {
  vi.resetModules();
  return import('./telemetry.js') as Promise<typeof import('./telemetry.js')>;
};

const makeTestDir = (): string => {
  const dir = mkdtempSync(join(TEST_BASE_DIR, 'case-'));
  process.env.OPENTABS_CONFIG_DIR = dir;
  return dir;
};

beforeEach(() => {
  vi.unstubAllEnvs();
  mockCapture.mockClear();
  mockIdentify.mockClear();
  ...
});
```

To test `trackPluginToolUsage`, you need telemetry initialized. Call `await tel.initTelemetry()` first (the existing tests do this). Then call `tel.trackPluginToolUsage(fakePlugin, 'send_message', { success: true, durationMs: 50 })`. Then assert on `mockCapture.mock.calls`.

Changes:
Add a new `describe('plugin_tool_used', ...)` block at the end of the file (before the final closing brace). Minimal skeleton:

```ts
describe('isTrackablePlugin', () => {
  const makePlugin = (overrides: Partial<RegisteredPlugin>): RegisteredPlugin => ({
    name: 'slack',
    version: '0.0.82',
    displayName: 'Slack',
    urlPatterns: [],
    excludePatterns: [],
    iife: '',
    tools: [],
    source: 'npm',
    npmPackageName: '@opentabs-dev/opentabs-plugin-slack',
    ...overrides,
  });

  test('accepts first-party npm plugin', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({}))).toBe(true);
  });

  test('rejects local plugin', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({ source: 'local', npmPackageName: undefined }))).toBe(false);
  });

  test('rejects third-party npm scope', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({ npmPackageName: '@someone/opentabs-plugin-foo', name: 'foo' }))).toBe(false);
  });

  test('rejects unscoped npm plugin', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({ npmPackageName: 'opentabs-plugin-foo', name: 'foo' }))).toBe(false);
  });

  test('rejects onlyfans even with first-party metadata', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({ name: 'onlyfans', npmPackageName: '@opentabs-dev/opentabs-plugin-onlyfans' }))).toBe(false);
  });

  test('rejects tinder even with first-party metadata', async () => {
    const tel = await importTelemetry();
    expect(tel.isTrackablePlugin(makePlugin({ name: 'tinder', npmPackageName: '@opentabs-dev/opentabs-plugin-tinder' }))).toBe(false);
  });
});

describe('trackPluginToolUsage', () => {
  test('fires plugin_tool_used event for trackable plugin', async () => {
    makeTestDir();
    const tel = await importTelemetry();
    await tel.initTelemetry();
    const plugin = { /* same shape as above, trackable */ } as RegisteredPlugin;
    tel.trackPluginToolUsage(plugin, 'send_message', { success: true, durationMs: 50 });
    const calls = mockCapture.mock.calls;
    const pluginToolCall = calls.find(([args]) => (args as { event: string }).event === 'plugin_tool_used');
    expect(pluginToolCall).toBeDefined();
    const props = (pluginToolCall![0] as { properties: Record<string, unknown> }).properties;
    expect(props).toMatchObject({
      plugin_name: 'slack',
      plugin_version: '0.0.82',
      tool_name: 'send_message',
      success: true,
      error_category: 'none',
      duration_bucket: '<100ms',
    });
    expect(props.session_id).toMatch(/^[0-9a-f-]{36}$/);
  });

  test('fires no event for untrackable plugin', async () => {
    makeTestDir();
    const tel = await importTelemetry();
    await tel.initTelemetry();
    mockCapture.mockClear(); // drop server_started event
    const plugin = { name: 'onlyfans', source: 'npm', npmPackageName: '@opentabs-dev/opentabs-plugin-onlyfans', /* fill other required fields */ } as RegisteredPlugin;
    tel.trackPluginToolUsage(plugin, 'send_message', { success: true, durationMs: 50 });
    const calls = mockCapture.mock.calls.filter(([args]) => (args as { event: string }).event === 'plugin_tool_used');
    expect(calls).toHaveLength(0);
  });
});

describe('computeDurationBucket', () => {
  test.each([
    [0, '<100ms'], [99, '<100ms'], [100, '<1s'], [999, '<1s'],
    [1000, '<5s'], [4999, '<5s'], [5000, '>=5s'], [99999, '>=5s'],
  ])('bucket for %dms is %s', async (ms, expected) => {
    const tel = await importTelemetry();
    expect(tel.computeDurationBucket(ms)).toBe(expected);
  });
});
```

Constraints:
- Use the existing `importTelemetry` and `makeTestDir` helpers — do NOT create new test harnesses.
- Use `mockCapture` to verify events — do NOT add new mocks.
- Use `as RegisteredPlugin` cast with a minimal factory function (`makePlugin`) — you only need to populate fields that isTrackablePlugin reads (name, source, npmPackageName) plus any that RegisteredPlugin marks required. Don't invent extra fields.
- Import `RegisteredPlugin` as a type: `import type { RegisteredPlugin } from './state.js';` at the top of the test file (or inside the describe if preferred).
- For `computeDurationBucket` to be testable, it must be exported from telemetry.ts. If US-001 didn't export it, add it to the exports in telemetry.ts in this story.

Trap warnings:
- The `server_started` event fires during `initTelemetry()`. The second test explicitly calls `mockCapture.mockClear()` after `initTelemetry()` to drop that event before the trackPluginToolUsage test assertions. Do the same in any test where you assert on exact call count.
- Prefer `.find()` for the plugin_tool_used event in the first test — `initTelemetry()` has already fired `server_started`, so `mockCapture.mock.calls[0]` is NOT the plugin_tool_used event.
- The PostHog mock's `capture` signature: `capture({ distinctId, event, properties })` — the argument is a single object, not positional. Destructure accordingly.
- TypeScript may complain if RegisteredPlugin has many required fields. If the type is onerous, define a `makePlugin` factory that provides defaults for every required field, and override only what the test needs.

